import { CopyToClipboard } from "@hunt/copy-to-clipboard";
import { cn } from "@hunt/styled-ui";
import { Check, Copy } from "lucide-react";
import React from "react";
import errorIcon from "../assets/error.svg";
import infoIcon from "../assets/info.svg";
import { BG_NATIVE_HEIGHT, BG_NATIVE_WIDTH } from "../terminus_constants";

const FULL_WIDTH = 289;

export type MessageVariant = "error" | "info" | "default";

export type TerminusMessageBoxProps = {
  children: React.ReactNode;
  variant?: MessageVariant;
  top?: number;
  left?: number;
  inline?: boolean;
  fullSize?: boolean;
  copyContentId?: string;
  className?: string;
  iconClassName?: string;
  textClassName?: string;
};

export const TerminusMessageBox = ({
  children,
  variant = "default",
  top,
  left,
  inline = false,
  fullSize = false,
  copyContentId,
  className,
  iconClassName,
  textClassName,
}: TerminusMessageBoxProps) => {
  const positionStyles =
    inline || fullSize
      ? {}
      : top !== undefined && left !== undefined
        ? {
            top: `${(top / BG_NATIVE_HEIGHT) * 100}%`,
            left: `${(left / BG_NATIVE_WIDTH) * 100}%`,
            width: `${(FULL_WIDTH / BG_NATIVE_WIDTH) * 100}%`,
          }
        : {};

  let borderColor = "border-white";
  let textColor = "text-white";
  let iconElement = null;

  if (variant === "error") {
    borderColor = "border-[#ff0000]";
    textColor = "text-term-red";
    iconElement = (
      <img
        src={errorIcon}
        alt=""
        aria-hidden="true"
        className={cn("w-1/4", iconClassName)}
      />
    );
  } else if (variant === "info") {
    borderColor = "border-[#00ff00]";
    textColor = "text-[#00ff00]";
    iconElement = (
      <img
        src={infoIcon}
        alt=""
        aria-hidden="true"
        className={cn("w-1/4 select-none", iconClassName)}
      />
    );
  }

  return (
    <div
      className={cn(
        "flex items-center gap-2 bg-black/80 border-2 border-dashed text-sm font-code px-3 py-2",
        borderColor,
        inline || fullSize ? "relative" : "absolute min-h-20",
        fullSize && "w-full h-full",
        className,
      )}
      style={positionStyles}
    >
      {iconElement}
      <div
        className={cn(
          "flex-1 min-w-0 h-fit overflow-auto break-words max-h-[70px]",
          textColor,
          textClassName,
        )}
        id={copyContentId}
      >
        {children}
      </div>
      {copyContentId && (
        <CopyToClipboard
          contentId={copyContentId}
          variant="custom"
          className="absolute top-1 right-1"
          iconClassName="w-4 min-w-4 aspect-square p-px"
          tooltipClassname="w-fit"
          tooltipSide="right"
          tooltipBeforeCopy="Copy"
          iconAfterCopy={<Check color="white" className="w-full h-full" />}
          icon={<Copy color="white" className="w-full h-full" />}
        />
      )}
    </div>
  );
};
