import {
  ConditionalTooltip,
  twemojify as twemojifyOriginal,
} from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import { ArrowLeft, CircleHelpIcon } from "lucide-react";
import React, { useMemo, useRef } from "react";
import {
  TERMINUS_INPUT_MAX_CHARACTERS,
  TERMINUS_RATE_LIMIT_SECONDS,
} from "../../../../../utils/terminus";
import { IS_STATIC_SITE } from "../../../../utils/staticSite";
import TerminusErrorBox from "../TerminusMessageBox/TerminusError";
import activityLogScreen from "../assets/activity_log.svg";
import terminusBg from "../assets/background.png";
import bottomRightScreenHoveredBg from "../assets/bottom_right_screen_hovered.png";
import leftScreenHoveredBg from "../assets/left_screen_hovered.png";
import metaProgress20 from "../assets/meta_progress/meta_progress_20.svg";
import metaProgress40 from "../assets/meta_progress/meta_progress_40.svg";
import metaProgress60 from "../assets/meta_progress/meta_progress_60.svg";
import metaProgress80 from "../assets/meta_progress/meta_progress_80.svg";
import metaSolved from "../assets/meta_progress/meta_solved.svg";
import metaUnlocked from "../assets/meta_progress/meta_unlocked.svg";
import monitorDecorations from "../assets/monitor_decorations.svg";
import singleMonitorDecoration from "../assets/single_monitor_decoration.svg";
import bottomRightScreenStaticBg from "../assets/static/bottom_right_screen_static.png";
import leftScreenStaticBg from "../assets/static/left_screen_static.png";
import topRightScreenStaticBg from "../assets/static/top_right_screen_static.png";
import submitButtonScreen from "../assets/submit_button.svg";
import topRightScreenHoveredBg from "../assets/top_right_screen_hovered.svg";
import {
  BG_NATIVE_HEIGHT,
  BG_NATIVE_WIDTH,
  SCREEN_POSITIONS,
  NUM_REGIONS,
  TERMINUS_TOOLTIP_STYLES,
} from "../terminus_constants";
import { type TerminusResponseState, type TerminusState } from "../types";
import { TerminusClipboard } from "./TerminusClipboard";

// Workaround for CI lint error where twemojify is typed as any/error
const twemojify = twemojifyOriginal as (
  text: string,
  className: string,
) => React.ReactNode[];

const READ_ONLY_SCREEN_STYLE =
  "absolute text-white text-center font-code text-sm whitespace-nowrap";
const LINK_SCREEN_STYLE =
  "absolute text-white text-center font-code text-sm whitespace-nowrap p-1 no-underline hover:text-white";

const META_PROGRESS_IMAGE = [
  metaProgress20,
  metaProgress40,
  metaProgress60,
  metaProgress80,
];

const TravelLogScreen = ({ readOnly }: { readOnly: boolean }) => {
  const leftScreenStyle = {
    left: `${(SCREEN_POSITIONS.leftScreen.x / BG_NATIVE_WIDTH) * 100}%`,
    top: `${(SCREEN_POSITIONS.leftScreen.y / BG_NATIVE_HEIGHT) * 100}%`,
    width: `${(SCREEN_POSITIONS.leftScreen.width / BG_NATIVE_WIDTH) * 100}%`,
    height: `${(SCREEN_POSITIONS.leftScreen.height / BG_NATIVE_HEIGHT) * 100}%`,
  };
  return readOnly ? (
    <div className={READ_ONLY_SCREEN_STYLE} style={leftScreenStyle}>
      <img
        src={leftScreenStaticBg}
        alt=""
        aria-hidden="true"
        className="pointer-events-none select-none w-full h-full"
      />
    </div>
  ) : (
    <a
      className={cn(LINK_SCREEN_STYLE, "group/travel-log")}
      style={leftScreenStyle}
      href="/rounds/terminus/travel_log"
      aria-label="Go to travel log"
    >
      <img
        src={leftScreenHoveredBg}
        alt=""
        aria-hidden="true"
        className="absolute top-0 left-0 w-full h-full pointer-events-none select-none z-0 transform-gpu drop-shadow-[0_0_10px_#569356] invisible group-hover/travel-log:visible group-focus-visible/travel-log:visible"
      />
      <div className="relative h-full flex flex-col items-center justify-center z-10">
        <span className="-skew-y-12 -mb-1">TRAVEL LOG</span>
        <img
          src={activityLogScreen}
          alt=""
          aria-hidden="true"
          className="pointer-events-none select-none mx-1"
        />
      </div>
    </a>
  );
};

const MetaProgressCircle = ({ solvedMetas }: { solvedMetas: number }) => {
  return solvedMetas === 0 ? (
    <div className="relative w-full h-full skew-y-6 flex items-center justify-center">
      <img
        src={singleMonitorDecoration}
        alt=""
        aria-hidden="true"
        className="pointer-events-none select-none"
      />
    </div>
  ) : (
    <ConditionalTooltip
      tooltip="Meta unlock progress"
      className={cn(TERMINUS_TOOLTIP_STYLES, "text-base")}
    >
      <div
        className="relative w-full h-full skew-y-6 p-1 flex items-center justify-center"
        aria-label={`Meta unlock progress: ${solvedMetas} / ${NUM_REGIONS - 1}`}
      >
        <img
          src={META_PROGRESS_IMAGE[solvedMetas - 1]}
          alt=""
          aria-hidden="true"
          className="pointer-events-none select-none mx-1"
        />
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-white text-sm">
          {solvedMetas}/{NUM_REGIONS - 1}
        </div>
      </div>
    </ConditionalTooltip>
  );
};

const MetaProgressScreen = ({
  state,
  readOnly,
}: {
  state: TerminusState | null;
  readOnly: boolean;
}) => {
  const metaProgress = useMemo(() => {
    if (!state) {
      return 0;
    }

    const metaPuzzles = state.puzzles.filter((puzzle) => {
      if (puzzle.is_final_meta) {
        return false;
      }
      return puzzle.is_meta;
    });
    return metaPuzzles.filter((puzzle) => {
      return !!puzzle.puzzle.answer;
    }).length;
  }, [state]);

  const topRightScreenStyle = {
    left: `${(SCREEN_POSITIONS.topRightScreen.x / BG_NATIVE_WIDTH) * 100}%`,
    top: `${(SCREEN_POSITIONS.topRightScreen.y / BG_NATIVE_HEIGHT) * 100}%`,
    width: `${(SCREEN_POSITIONS.topRightScreen.width / BG_NATIVE_WIDTH) * 100}%`,
    height: `${(SCREEN_POSITIONS.topRightScreen.height / BG_NATIVE_HEIGHT) * 100}%`,
  };

  if (readOnly) {
    return (
      <div className={READ_ONLY_SCREEN_STYLE} style={topRightScreenStyle}>
        <img
          src={topRightScreenStaticBg}
          alt=""
          aria-hidden="true"
          className="pointer-events-none select-none w-full h-full"
        />
      </div>
    );
  }

  return !state?.meta ? (
    <div
      className={cn(READ_ONLY_SCREEN_STYLE, "p-1")}
      style={topRightScreenStyle}
    >
      <MetaProgressCircle solvedMetas={metaProgress} />
    </div>
  ) : (
    // If the final meta is unlocked, then link to the meta in the screen.
    <a
      className={cn(LINK_SCREEN_STYLE, "group/meta-entrypoint")}
      style={topRightScreenStyle}
      href={`/puzzles/${state.meta.puzzle.slug}`}
      aria-label={`Go to meta: ${state.meta.puzzle.title}`}
    >
      <img
        src={topRightScreenHoveredBg}
        alt=""
        aria-hidden="true"
        className="absolute top-0 left-0 w-full h-full pointer-events-none select-none z-0 transform-gpu drop-shadow-[0_0_10px_#569356] invisible group-hover/meta-entrypoint:visible group-focus-visible/meta-entrypoint:visible"
      />
      <div className="relative h-full flex flex-col items-center justify-center z-10 p-1">
        <img
          src={state.meta.puzzle.answer ? metaSolved : metaUnlocked}
          alt=""
          aria-hidden="true"
          className="pointer-events-none select-none mx-1 skew-y-6"
        />
      </div>
    </a>
  );
};

const BottomRightScreen = ({
  readOnly,
  isMeta,
}: {
  readOnly: boolean;
  isMeta: boolean;
}) => {
  const bottomRightScreenStyle = {
    left: `${(SCREEN_POSITIONS.bottomRightScreen.x / BG_NATIVE_WIDTH) * 100}%`,
    top: `${(SCREEN_POSITIONS.bottomRightScreen.y / BG_NATIVE_HEIGHT) * 100}%`,
    width: `${(SCREEN_POSITIONS.bottomRightScreen.width / BG_NATIVE_WIDTH) * 100}%`,
    height: `${(SCREEN_POSITIONS.bottomRightScreen.height / BG_NATIVE_HEIGHT) * 100}%`,
  };

  if (isMeta) {
    return (
      <div
        id="copy-to-clipboard-container"
        className={cn(
          READ_ONLY_SCREEN_STYLE,
          "flex items-center justify-center",
        )}
        style={bottomRightScreenStyle}
      >
        <TerminusClipboard />
      </div>
    );
  }

  if (readOnly) {
    return (
      <div className={READ_ONLY_SCREEN_STYLE} style={bottomRightScreenStyle}>
        <img
          src={bottomRightScreenStaticBg}
          alt=""
          aria-hidden="true"
          className="pointer-events-none select-none w-full h-full"
        />
      </div>
    );
  }

  return (
    <button
      type="submit"
      className={cn(LINK_SCREEN_STYLE, "group/submit-button-screen")}
      style={bottomRightScreenStyle}
      aria-label="Submit next destination"
    >
      <img
        src={bottomRightScreenHoveredBg}
        alt=""
        aria-hidden="true"
        className="absolute top-0 left-0 w-full h-full pointer-events-none select-none z-0 transform-gpu drop-shadow-[0_0_10px_#569356] invisible group-hover/submit-button-screen:visible group-focus-visible/submit-button-screen:visible"
      />
      <div className="relative h-full flex flex-col items-center justify-center z-10">
        <span className="skew-y-12 -mb-1">SUBMIT</span>
        <img
          src={submitButtonScreen}
          alt=""
          aria-hidden="true"
          className="pointer-events-none select-none px-2"
        />
      </div>
    </button>
  );
};

const MainScreen = ({
  response,
  globalError,
  clientError,
  rateLimitEndTimestamp,
  isLoading,
  readOnly,
  metaFlavortext,
  inputValue,
  setInputValue,
}: {
  response: TerminusResponseState | null;
  globalError: string | null;
  clientError: string | null;
  rateLimitEndTimestamp: string | null;
  isLoading: boolean;
  readOnly: boolean;
  metaFlavortext: React.ReactNode | null;
  inputValue?: string;
  setInputValue?: (value: string) => void;
}) => {
  const inputRef = useRef<HTMLInputElement>(null);
  const textRef = useRef<HTMLDivElement>(null);

  const mainScreenStyle = {
    left: `${(SCREEN_POSITIONS.mainScreen.x / BG_NATIVE_WIDTH) * 100}%`,
    top: `${(SCREEN_POSITIONS.mainScreen.y / BG_NATIVE_HEIGHT) * 100}%`,
    width: `${(SCREEN_POSITIONS.mainScreen.width / BG_NATIVE_WIDTH) * 100}%`,
    height: `${(SCREEN_POSITIONS.mainScreen.height / BG_NATIVE_HEIGHT) * 100}%`,
  };

  const value = isLoading ? "Loading..." : inputValue;

  return (
    <>
      {/* Central screen */}
      <div
        className={cn(
          "absolute text-base font-code flex flex-col gap-1",
          globalError
            ? "text-term-red"
            : "text-term-green cursor-text justify-between",
          readOnly && "cursor-not-allowed justify-start gap-2",
          readOnly && globalError && "gap-1",
          metaFlavortext ? "p-4 cursor-auto" : "px-3 pt-1.5 pb-4",
        )}
        style={mainScreenStyle}
      >
        {/* Current universe display */}
        {!metaFlavortext ? (
          <div className="flex flex-col">
            <p className="ml-auto">
              {readOnly ? "Snapshot of Universe" : "Current Universe"}
            </p>
            <div
              className={cn(
                "px-1 overflow-x-auto text-end mb-1 whitespace-pre",
                globalError ? "bg-term-red/25" : "bg-term-green/25 ",
              )}
            >
              {response?.normalized_input === ""
                ? "<empty input>"
                : // The emojis look better visually if they have a small bottom margin.
                  twemojify(response?.normalized_input ?? "N/A", "h-4 mb-0.5")}
            </div>
          </div>
        ) : (
          <div className="absolute top-0 left-0 p-3 w-full h-full font-mono text-center">
            {metaFlavortext}
          </div>
        )}
        {(!readOnly || globalError) && !metaFlavortext && (
          <div className="relative min-h-[60px] flex items-center">
            {clientError || globalError || rateLimitEndTimestamp ? (
              <TerminusErrorBox inline fullSize className="py-1 text-xs">
                {clientError || globalError || (
                  <>
                    Rate limited. Try again at{" "}
                    <span className="text-white">{rateLimitEndTimestamp}</span>.
                  </>
                )}
              </TerminusErrorBox>
            ) : (
              // Monitor decorations
              <img
                src={monitorDecorations}
                alt=""
                aria-hidden="true"
                className="pointer-events-none select-none"
                width="98%"
              />
            )}
          </div>
        )}
        {readOnly && !metaFlavortext && (
          <div className="text-white text-base term-2xl:text-lg text-center">
            Snapshots are not interactive.
          </div>
        )}
        {/* Input value display */}
        {!readOnly && (
          <div className="flex flex-col text-white">
            <label htmlFor="terminus-universe-input">
              Input next destination:
            </label>

            <div className="flex items-center gap-1 bg-white/25 px-1">
              {`>`}
              <div className="relative min-w-0 grow h-full flex items-center">
                <input
                  id="terminus-universe-input"
                  ref={inputRef}
                  type="text"
                  className="absolute top-0 left-0 w-full bg-transparent border-0 outline-none focus-visible:outline-none text-transparent caret-white"
                  value={value}
                  onChange={(e) => {
                    setInputValue?.(e.target.value);
                  }}
                  onScroll={() => {
                    textRef.current?.scrollTo({
                      left: inputRef.current?.scrollLeft ?? 0,
                    });
                  }}
                  maxLength={TERMINUS_INPUT_MAX_CHARACTERS}
                  // eslint-disable-next-line jsx-a11y/no-autofocus
                  autoFocus
                />
                <div
                  ref={textRef}
                  className="overflow-hidden"
                  aria-hidden="true"
                >
                  <span className="whitespace-pre">
                    {/* The emojis look better visually if they have a small bottom margin. */}
                    {twemojify(value ?? "", "h-4 mb-0.5")}
                  </span>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </>
  );
};

export const TerminusBackButton = ({
  href,
  text,
  className,
}: {
  href: string;
  text: string;
  className?: string;
}) => {
  return (
    <a
      href={href}
      className={cn(
        "absolute top-20 left-4 md:top-24 md:left-8 z-10 flex items-center gap-1 no-underline whitespace-nowrap text-term-green hover:text-term-green bg-term-screen pl-3 pr-4 py-2 rounded-sm hover:bg-term-screen-hover focus-visible:bg-term-screen-hover print:hidden",
        className,
      )}
      aria-label={text}
    >
      <ArrowLeft />
      {text}
    </a>
  );
};

/**
 * The background image for the round page.
 */
export const TerminusBackgroundWrapper = ({
  children,
  backButtonProps,
  showHelpIcon = false,
  className,
}: {
  children: React.ReactNode;
  backButtonProps?: {
    text: string;
    href: string;
  };
  showHelpIcon?: boolean;
  className?: string;
}) => {
  const tooltipText = useMemo(() => {
    let text = "Type your next destination in the terminal screen.";

    if (!IS_STATIC_SITE && TERMINUS_RATE_LIMIT_SECONDS) {
      text += ` You may submit a guess every ${TERMINUS_RATE_LIMIT_SECONDS} second${TERMINUS_RATE_LIMIT_SECONDS === 1 ? "" : "s"}.`;
    }

    return text;
  }, []);

  return (
    <div className={cn("relative w-fit", className)}>
      {backButtonProps && (
        <TerminusBackButton
          href={backButtonProps.href}
          text={backButtonProps.text}
        />
      )}
      {showHelpIcon && (
        <ConditionalTooltip
          tooltip={tooltipText}
          className={cn(TERMINUS_TOOLTIP_STYLES, "text-base")}
          side="right"
          align="start"
        >
          <CircleHelpIcon
            className="absolute top-24 left-4 w-10 h-10 z-10"
            aria-label="Help"
          />
        </ConditionalTooltip>
      )}
      <div
        // We can adjust the min-width if we want to make the background more responsive.
        className="relative min-w-[1400px] w-screen flex bg-contain bg-no-repeat bg-top"
        style={{
          backgroundImage: `url(${terminusBg})`,
          aspectRatio: `${BG_NATIVE_WIDTH / BG_NATIVE_HEIGHT}`,
        }}
      >
        {children}
      </div>
    </div>
  );
};

type TerminusInteractiveScreensProps = {
  response?: TerminusResponseState | null;
  state?: TerminusState | null;
  inputValue?: string;
  setInputValue?: (value: string) => void;
  rateLimitEndTimestamp?: string | null;
  clientError?: string | null;
  isLoading?: boolean;
  readOnly?: boolean;
  metaFlavortext?: React.ReactNode;
};

export const TerminusInteractiveScreens = ({
  response = null,
  state = null,
  inputValue,
  setInputValue,
  rateLimitEndTimestamp = null,
  clientError,
  isLoading = false,
  readOnly = false,
  metaFlavortext = null,
}: TerminusInteractiveScreensProps) => {
  const globalError = useMemo(() => {
    return response?.status === "error" ? response.message : null;
  }, [response]);

  return (
    <>
      <TravelLogScreen readOnly={readOnly} />
      <MainScreen
        response={response}
        globalError={globalError}
        clientError={clientError ?? null}
        inputValue={inputValue}
        setInputValue={setInputValue}
        rateLimitEndTimestamp={rateLimitEndTimestamp}
        isLoading={isLoading}
        readOnly={readOnly}
        metaFlavortext={metaFlavortext}
      />
      <MetaProgressScreen state={state} readOnly={readOnly} />
      <BottomRightScreen readOnly={readOnly} isMeta={!!metaFlavortext} />
    </>
  );
};
