export const getTerminusAlias = (slug: string): string => {
  return TERMINUS_PUZZLE_ALIAS_MAP[slug] ?? slug;
};

const TERMINUS_SLUGS = new Set([
  ...TERMINUS_FEEDER_SLUGS,
  ...TERMINUS_META_SLUGS,
]);

type TerminusLocalDb = {
  terminus_state: {
    key: string;
    value: TerminusLocalState;
  };
};

export type TerminusLocalState = {
  unlocked: string[];
  travelLog: TerminusTravelLogEntry[];
  nextLogId: number;
};

const DEFAULT_LOCAL_STATE: TerminusLocalState = {
  unlocked: [],
  travelLog: [],
  nextLogId: 1,
};

let dbPromise: Promise<IDBPDatabase<TerminusLocalDb>> | null = null;
let memoryFallbackState: TerminusLocalState | null = null;

const openTerminusDb = async () => {
  if (!dbPromise) {
    dbPromise = openDB<TerminusLocalDb>(
      TERMINUS_LOCAL_DB_NAME,
      TERMINUS_LOCAL_DB_VERSION,
      {
        upgrade(db) {
          if (!db.objectStoreNames.contains(TERMINUS_LOCAL_STORE)) {
            db.createObjectStore(TERMINUS_LOCAL_STORE);
          }
        },
      },
    );
  }
  return dbPromise;
};

const computeNextLogId = (entries: TerminusTravelLogEntry[]): number => {
  const maxId = entries.reduce(
    (max, entry) => (entry.id > max ? entry.id : max),
    0,
  );
  return maxId + 1;
};

const normalizeLocalState = (
  state?: Partial<TerminusLocalState> | null,
): TerminusLocalState => {
  if (!state) {
    return { ...DEFAULT_LOCAL_STATE };
  }
  const unlocked = Array.isArray(state.unlocked)
    ? state.unlocked.filter((slug): slug is string => typeof slug === "string")
    : [];
  const travelLog = Array.isArray(state.travelLog)
    ? state.travelLog.filter(
        (entry): entry is TerminusTravelLogEntry =>
          Boolean(entry) &&
          typeof entry.id === "number" &&
          typeof entry.timestamp === "string" &&
          typeof entry.terminusState === "string" &&
          Array.isArray(entry.puzzles),
      )
    : [];
  const nextLogId = Number.isFinite(state.nextLogId)
    ? Number(state.nextLogId)
    : computeNextLogId(travelLog);
  return {
    unlocked,
    travelLog,
    nextLogId,
  };
};

export const loadTerminusLocalState = async (): Promise<TerminusLocalState> => {
  if (typeof window === "undefined") {
    return { ...DEFAULT_LOCAL_STATE };
  }

  try {
    const db = await openTerminusDb();
    const stored = await db.get(TERMINUS_LOCAL_STORE, TERMINUS_LOCAL_KEY);
    const normalized = normalizeLocalState(stored ?? undefined);
    if (!stored) {
      await db.put(TERMINUS_LOCAL_STORE, normalized, TERMINUS_LOCAL_KEY);
    }
    return normalized;
  } catch {
    if (!memoryFallbackState) {
      memoryFallbackState = { ...DEFAULT_LOCAL_STATE };
    }
    return { ...memoryFallbackState };
  }
};

export const saveTerminusLocalState = async (
  state: TerminusLocalState,
): Promise<void> => {
  if (typeof window === "undefined") {
    return;
  }
  const normalized = normalizeLocalState(state);
  try {
    const db = await openTerminusDb();
    await db.put(TERMINUS_LOCAL_STORE, normalized, TERMINUS_LOCAL_KEY);
  } catch {
    memoryFallbackState = normalized;
  }
};

const buildActivityLogEntryFromTravelEntry = (
  entry: TerminusTravelLogEntry,
): TerminusActivityLogEntry => {
  return {
    id: entry.id,
    timestamp: new Date(entry.timestamp),
    team_id: 0,
    terminus_str: entry.terminusState,
    error_message: entry.errorMessage,
    data: {
      puzzles: entry.puzzles.map((puzzle) => ({
        slug: puzzle.slug,
        alias: puzzle.alias,
        in_universe: puzzle.inUniverse,
        newly_unlocked: puzzle.newlyUnlocked,
        solved: puzzle.solved,
        title: puzzle.title ?? puzzle.alias ?? puzzle.slug,
      })),
    },
  };
};

export const buildTerminusResponseFromEvaluation = (
  evaluation: TerminusEvaluationResult,
  entry: TerminusTravelLogEntry,
): TerminusResponseState => {
  const activityEntry = buildActivityLogEntryFromTravelEntry(entry);
  const hydrated = hydrateTerminusEvaluationFromEntry(
    evaluation,
    activityEntry,
  );
  if (hydrated.status === "success") {
    return {
      ...hydrated,
      newly_unlocked_puzzles: entry.puzzles
        .filter((puzzle) => puzzle.newlyUnlocked)
        .map((puzzle) => puzzle.slug),
    };
  }
  return hydrated;
};

export const buildTerminusResponseFromEntry = (
  entry: TerminusTravelLogEntry,
): TerminusResponseState => {
  const evaluation = evaluateTerminus(entry.terminusState);
  return buildTerminusResponseFromEvaluation(evaluation, entry);
};

const getTitleForSlug = (
  slug: string,
  puzzleBySlug: Map<string, TerminusPuzzleDisplay>,
): string => {
  const puzzle = puzzleBySlug.get(slug);
  return puzzle?.puzzle.title ?? slug;
};

export const buildTerminusSnapshotState = (
  baseState: TerminusState,
  entry: TerminusTravelLogEntry,
): TerminusState => {
  const puzzleBySlug = new Map(
    baseState.puzzles.map((puzzle) => [puzzle.puzzle.slug, puzzle]),
  );
  const puzzles = entry.puzzles
    .flatMap((entryPuzzle): TerminusPuzzleDisplay[] => {
      const base = puzzleBySlug.get(entryPuzzle.slug);
      if (!base) {
        return [];
      }
      const snapshotPuzzle: TerminusPuzzleDisplay = {
        ...base,
        puzzle: {
          ...base.puzzle,
          answer: entryPuzzle.solved
            ? (base.puzzle.answer ?? "Solved")
            : undefined,
          state: "unlocked",
        },
      };
      return [snapshotPuzzle];
    })
    .sort((a, b) => {
      const regionA = a.region ?? Number.POSITIVE_INFINITY;
      const regionB = b.region ?? Number.POSITIVE_INFINITY;
      if (regionA !== regionB) {
        return regionA - regionB;
      }
      return a.puzzle.title.localeCompare(b.puzzle.title);
    });

  const finalMetaSlug = baseState.meta?.puzzle.slug ?? "mixed_media";
  const meta =
    puzzles.find((puzzle) => puzzle.puzzle.slug === finalMetaSlug) ?? null;

  return {
    ...baseState,
    puzzles,
    progress: {
      unlocked: entry.puzzles.map((puzzle) => puzzle.slug),
      solved: entry.puzzles
        .filter((puzzle) => puzzle.solved)
        .map((p) => p.slug),
    },
    meta,
  };
};

export const applyTerminusSubmission = ({
  input,
  currentState,
  basePuzzles,
  solvedMap,
}: {
  input: string;
  currentState: TerminusLocalState;
  basePuzzles: TerminusPuzzleDisplay[];
  solvedMap: LocalSolvedPuzzleMap;
}): {
  nextState: TerminusLocalState;
  entry: TerminusTravelLogEntry;
  response: TerminusResponseState;
} => {
  const puzzleBySlug = new Map(
    basePuzzles.map((puzzle) => [puzzle.puzzle.slug, puzzle]),
  );

  const evaluation = evaluateTerminus(input);
  const normalizedInput = evaluation.normalized_input;
  const puzzleSlugs = getTerminusPuzzleSlugs(evaluation).filter((slug) =>
    TERMINUS_SLUGS.has(slug),
  );

  const unlockedSet = new Set(
    currentState.unlocked.filter((slug) => TERMINUS_SLUGS.has(slug)),
  );
  const newlyUnlocked = puzzleSlugs.filter((slug) => !unlockedSet.has(slug));
  const nextUnlocked = Array.from(new Set([...unlockedSet, ...newlyUnlocked]));

  const inUniverse = new Set(puzzleSlugs);
  const newlyUnlockedSet = new Set(newlyUnlocked);
  const solvedSet = new Set(Object.keys(solvedMap));

  const puzzles = nextUnlocked.map((slug) => ({
    slug,
    alias: getTerminusAlias(slug),
    inUniverse: inUniverse.has(slug),
    newlyUnlocked: newlyUnlockedSet.has(slug),
    solved: solvedSet.has(slug),
    title: getTitleForSlug(slug, puzzleBySlug),
  }));

  const entry: TerminusTravelLogEntry = {
    id: currentState.nextLogId,
    timestamp: new Date().toISOString(),
    terminusState: normalizedInput,
    puzzles,
    errorMessage:
      evaluation.status === "error" ? evaluation.message : undefined,
  };

  const nextState: TerminusLocalState = {
    unlocked: nextUnlocked,
    travelLog: [...currentState.travelLog, entry],
    nextLogId: currentState.nextLogId + 1,
  };

  const response = buildTerminusResponseFromEvaluation(evaluation, entry);

  return { nextState, entry, response };
};

export const getLatestTravelLogEntry = (
  state: TerminusLocalState,
): TerminusTravelLogEntry | null => {
  if (state.travelLog.length === 0) {
    return null;
  }
  return state.travelLog[state.travelLog.length - 1];
};
