import {
  TERMINUS_FEEDER_SLUGS_BY_TYPE,
  TERMINUS_META_SLUGS_BY_TYPE,
  TERMINUS_TYPES,
  type TerminusType,
} from "@hunt/hunt-data";
import {
  SPECIAL_META,
  TARGETS,
  resultFunctions,
  validateResult,
} from "../../../../api/terminus/config";
import { overallConversions } from "../../../../api/terminus/conversions";
import { isFailure } from "../../../../api/terminus/helpers";
import { overallParse } from "../../../../api/terminus/parsers";
import type {
  ConversionResult,
  ParsedEntry,
  TerminusEvaluationResult,
  TerminusOutput,
  TypeValueMap,
} from "../../../../api/terminus/types";
import { normalizeTerminusValue } from "../../../../utils/terminus";

type OutcomesByType = Record<TerminusType, TerminusOutput>;

type ConversionMap = Record<
  TerminusType,
  ConversionResult<TypeValueMap[TerminusType]>
>;

const getOutcomesByType = (
  conversions: ConversionMap,
  originalType: TerminusType,
  hideOutputValues: boolean,
): OutcomesByType => {
  const output: Partial<OutcomesByType> = {};

  const processTarget = (targetType: TerminusType): void => {
    const converted = originalType !== targetType;
    const conversion = conversions[targetType];
    if (isFailure(conversion)) {
      output[targetType] = {
        status: "failure",
        type: targetType,
        reason: "Conversion failure (_)",
        converted,
        convertedValue: hideOutputValues
          ? "???"
          : (conversion[1] as string | number),
      };
      return;
    }

    const convertedValue = conversion as TypeValueMap[TerminusType];
    const validateFn = validateResult[targetType] as (
      value: TypeValueMap[TerminusType],
    ) => ReturnType<(typeof validateResult)[TerminusType]>;
    const validationFailures = validateFn(convertedValue).filter(([ok]) => !ok);

    if (validationFailures.length > 0) {
      const [, reason] = validationFailures[0];
      output[targetType] = {
        status: "failure",
        type: targetType,
        reason: `Getting puzzle failed (_ ${reason})`,
        converted,
        convertedValue: hideOutputValues ? "???" : convertedValue,
      };
      return;
    }

    const isTarget = TARGETS[targetType].some(
      (target) => target === convertedValue,
    );

    if (isTarget) {
      output[targetType] = {
        status: "meta",
        type: targetType,
        converted,
        convertedValue: hideOutputValues ? "???" : convertedValue,
        puzzle_slug: TERMINUS_META_SLUGS_BY_TYPE[targetType],
      };
      return;
    }

    const resultFn = resultFunctions[targetType] as (
      value: TypeValueMap[TerminusType],
    ) => number[];
    const puzzles = resultFn(convertedValue);
    if (puzzles.length > 0) {
      const puzzleSlugs = puzzles
        .map((index) => {
          const slugs = TERMINUS_FEEDER_SLUGS_BY_TYPE[targetType];
          return slugs[index] ?? null;
        })
        .filter((slug) => slug !== null);
      output[targetType] = {
        status: "puzzle_list",
        type: targetType,
        converted,
        convertedValue: hideOutputValues ? "???" : convertedValue,
        puzzle_slugs: puzzleSlugs,
      };
    } else {
      output[targetType] = {
        status: "no_puzzle",
        type: targetType,
        converted,
        convertedValue: hideOutputValues ? "???" : convertedValue,
      };
    }
  };

  for (const targetType of TERMINUS_TYPES) {
    processTarget(targetType);
  }

  return output as OutcomesByType;
};

const isSpecialMetaInput = (parsedEntry: ParsedEntry): boolean => {
  return SPECIAL_META[parsedEntry.type] === parsedEntry.value;
};

export const evaluateTerminus = (input: string): TerminusEvaluationResult => {
  const normalizedInput = normalizeTerminusValue(input);
  const parsedEntry = overallParse(normalizedInput);
  if (!parsedEntry) {
    return {
      normalized_input: normalizedInput,
      status: "error",
      message: "Nothing was found in this universe.",
    };
  }
  const conversions = overallConversions(parsedEntry.type, parsedEntry.value);
  const results = getOutcomesByType(
    conversions,
    parsedEntry.type,
    isSpecialMetaInput(parsedEntry),
  );
  return {
    normalized_input: normalizedInput,
    status: "success",
    results,
  };
};

export const getTerminusPuzzleSlugs = (
  evalResult: TerminusEvaluationResult,
): string[] => {
  if (evalResult.status !== "success") {
    return [];
  }
  return Object.values(evalResult.results).flatMap((result) => {
    if (result.status === "puzzle_list") {
      return result.puzzle_slugs;
    }
    if (result.status === "meta") {
      return [result.puzzle_slug];
    }
    return [];
  });
};
