import {
  TERMINUS_META_SLUGS_BY_TYPE,
  TERMINUS_TYPES,
  type TerminusType,
} from "@hunt/hunt-data";
import { type TerminusActivityLogEntry } from "@hunt/public-client";
import { type TeamStateIntermediate } from "@hunt/team-state";
import { TYPE_NAME_TABLE } from "./config";
import {
  type TerminusEvaluationResult,
  type HydratedTerminusEvaluationResult,
  type HydratedTerminusOutput,
  type TerminusOutput,
  type DisplayFailure,
  type DisplayNoPuzzle,
  type DisplayPuzzleList,
  type DisplayMeta,
  type HydratedDisplayFailure,
  type HydratedDisplayNoPuzzle,
  type HydratedDisplayPuzzleList,
  type HydratedDisplayMeta,
} from "./types";

export const getCoreTerminusMetasSolvedFromEntry = (
  entry: TerminusActivityLogEntry,
): Record<TerminusType, boolean> => {
  const solved =
    entry.data?.puzzles
      .filter((puzzle) => puzzle.solved)
      .map((puzzle) => puzzle.slug) ?? [];
  return TERMINUS_TYPES.reduce<Record<TerminusType, boolean>>(
    (acc, type) => {
      acc[type] = solved.includes(TERMINUS_META_SLUGS_BY_TYPE[type]);
      return acc;
    },
    {} as Record<TerminusType, boolean>,
  );
};

export const getCoreTerminusMetasSolvedFromTeamState = (
  teamState: TeamStateIntermediate,
): Record<TerminusType, boolean> => {
  const solved = teamState.puzzles_solved;
  return TERMINUS_TYPES.reduce<Record<TerminusType, boolean>>(
    (acc, type) => {
      acc[type] = solved.has(TERMINUS_META_SLUGS_BY_TYPE[type]);
      return acc;
    },
    {} as Record<TerminusType, boolean>,
  );
};

export const hydrateDisplayFailure = (
  { type, reason, converted, convertedValue }: DisplayFailure,
  solved: boolean,
): HydratedDisplayFailure => {
  let message: string;
  if (converted) {
    if (reason.includes("Conversion failure")) {
      const replacement = solved
        ? `(${convertedValue} to ${TYPE_NAME_TABLE[type]})`
        : "";
      message = reason.replace(/\(_\)/g, replacement);
    } else {
      const replacement =
        "converted " +
        (solved ? `${TYPE_NAME_TABLE[type]} ${convertedValue}` : "value");
      message = reason.replace(/_/g, replacement);
    }
  } else if (solved) {
    message = reason.replace(
      /_/g,
      `${TYPE_NAME_TABLE[type]} ${convertedValue}`,
    );
  } else {
    message = reason.replace(/_ (has|is) | \(_\)/g, "");
  }
  return {
    status: "failure",
    type,
    message,
  };
};

export const hydrateDisplayMeta = (
  { type, puzzle_slug, converted, convertedValue }: DisplayMeta,
  solved: boolean,
): HydratedDisplayMeta => {
  return {
    status: "meta",
    type,
    puzzle_slug,
    message: solved
      ? `${converted ? `Converted ${TYPE_NAME_TABLE[type]}: ` : `${TYPE_NAME_TABLE[type]}: `}${convertedValue}`
      : converted
        ? "A conversion happened"
        : null,
  };
};

export const hydrateDisplayNoPuzzle = (
  { type, converted, convertedValue }: DisplayNoPuzzle,
  solved: boolean,
): HydratedDisplayNoPuzzle => {
  return {
    status: "no_puzzle",
    type,
    message: solved
      ? `No puzzle found (${converted ? `Converted ${TYPE_NAME_TABLE[type]}: ` : `${TYPE_NAME_TABLE[type]}: `}${convertedValue})`
      : "No puzzle found" + (converted ? " (A conversion happened)" : ""),
  };
};

export const hydrateDisplayPuzzleList = (
  { type, puzzle_slugs, converted, convertedValue }: DisplayPuzzleList,
  solved: boolean,
): HydratedDisplayPuzzleList => {
  return {
    status: "puzzle_list",
    type,
    puzzle_slugs,
    message: solved
      ? `${converted ? `Converted ${TYPE_NAME_TABLE[type]}: ` : `${TYPE_NAME_TABLE[type]}: `}${convertedValue}`
      : converted
        ? "A conversion happened"
        : null,
  };
};

const hydrateResultImpl = (
  result: TerminusOutput,
  solved: boolean,
): HydratedTerminusOutput => {
  switch (result.status) {
    case "failure":
      return hydrateDisplayFailure(result, solved);

    case "meta":
      return hydrateDisplayMeta(result, solved);

    case "no_puzzle":
      return hydrateDisplayNoPuzzle(result, solved);

    case "puzzle_list":
      return hydrateDisplayPuzzleList(result, solved);

    default: {
      // Exhaustiveness check – will error if a new status is added
      const _exhaustive: never = result;
      return _exhaustive;
    }
  }
};

export const hydrateTerminusEvaluationFromEntry = (
  evaluation: TerminusEvaluationResult,
  entry: TerminusActivityLogEntry,
): HydratedTerminusEvaluationResult => {
  if (evaluation.status === "error") {
    return evaluation;
  }

  const hydrateResult = (result: TerminusOutput): HydratedTerminusOutput => {
    const solved = getCoreTerminusMetasSolvedFromEntry(entry)[result.type];
    return hydrateResultImpl(result, solved);
  };

  const hydratedResults = {
    Zone1: hydrateResult(evaluation.results.Zone1),
    Zone2: hydrateResult(evaluation.results.Zone2),
    Zone3: hydrateResult(evaluation.results.Zone3),
    Zone4: hydrateResult(evaluation.results.Zone4),
    Zone5: hydrateResult(evaluation.results.Zone5),
    Zone6: hydrateResult(evaluation.results.Zone6),
  };
  return {
    ...evaluation,
    results: hydratedResults,
  };
};

export const hydrateTerminusEvaluation = (
  evaluation: TerminusEvaluationResult,
  teamState: TeamStateIntermediate,
): HydratedTerminusEvaluationResult => {
  if (evaluation.status === "error") {
    return evaluation;
  }

  const hydrateResult = (result: TerminusOutput): HydratedTerminusOutput => {
    const solved =
      getCoreTerminusMetasSolvedFromTeamState(teamState)[result.type];
    return hydrateResultImpl(result, solved);
  };

  const hydratedResults = {
    Zone1: hydrateResult(evaluation.results.Zone1),
    Zone2: hydrateResult(evaluation.results.Zone2),
    Zone3: hydrateResult(evaluation.results.Zone3),
    Zone4: hydrateResult(evaluation.results.Zone4),
    Zone5: hydrateResult(evaluation.results.Zone5),
    Zone6: hydrateResult(evaluation.results.Zone6),
  };

  return {
    ...evaluation,
    results: hydratedResults,
  };
};
