import React from "react";
import { TerminusMessageBox } from "./TerminusMessageBox";

type TerminusErrorBoxProps = {
  children: React.ReactNode;
  top?: number;
  left?: number;
  inline?: boolean;
  fullSize?: boolean;
  copyContentId?: string;
  className?: string;
  iconClassName?: string;
};

const TerminusErrorBox = ({
  children,
  top,
  left,
  inline = false,
  fullSize = false,
  copyContentId,
  className,
  iconClassName,
}: TerminusErrorBoxProps) => {
  return (
    <TerminusMessageBox
      variant="error"
      top={top}
      left={left}
      inline={inline}
      fullSize={fullSize}
      copyContentId={copyContentId}
      className={className}
      iconClassName={iconClassName}
    >
      {children}
    </TerminusMessageBox>
  );
};

export default TerminusErrorBox;
