import { TERMINUS_TYPES, type TerminusType } from "@hunt/hunt-data";
import { TERMINUS_COLOR_TABLE, TERMINUS_EMOJI_TABLE } from "./data";
import {
  calcDate,
  closestColor,
  colorify,
  dateName,
  findClosestKey,
  fromCode,
  HEX_TO_LETTER,
  isValidDate,
  LETTER_TO_HEX,
  numberName,
  parseBase26,
  parseDate,
  parseNumber,
  toBase26,
  toDigits,
} from "./helpers";
import type { ConversionResult, TypeValueMap } from "./types";

type ConversionFn<From extends TerminusType, To extends TerminusType> = (
  value: TypeValueMap[From],
) => ConversionResult<TypeValueMap[To]>;

type ConversionMap = {
  [F in TerminusType]: Partial<{
    [T in TerminusType]: ConversionFn<F, T>;
  }>;
};

export const convertFunctions: ConversionMap = {
  Zone1: {
    Zone5: (value) => fromCode(value.toString(16).toUpperCase()),
    Zone6: (value) => toBase26(value),
    Zone4: (value) =>
      value >= 1e15 ? [null, value.toString()] : numberName(value),
    Zone2: (value) => colorify(value.toString(16).toUpperCase()),
    Zone3: (value) => `${value}/1/1`,
  },
  Zone2: {
    Zone5: (value) => fromCode(value),
    Zone6: (value) => {
      let out = "";
      for (const digit of value) {
        out += HEX_TO_LETTER[digit];
      }
      return out;
    },
    Zone4: (value) => {
      const candidates = closestColor(value, Object.keys(TERMINUS_COLOR_TABLE));
      const best = candidates.find(
        (candidate) => candidate in TERMINUS_COLOR_TABLE,
      );
      return best ? TERMINUS_COLOR_TABLE[best].name : [null, value];
    },
    Zone1: (value) => Math.min(parseInt(value, 16), Number.MAX_VALUE),
    Zone3: (value) => {
      let digits = "";
      for (const digit of value) {
        digits += String(parseInt(digit, 16));
      }
      if (digits.length <= 4) {
        return [null, digits];
      }
      const year = digits.slice(0, -4).replace(/^0*/g, "") || "0";
      const month = digits.slice(-4, -2).replace(/^0*/g, "") || "0";
      const day = digits.slice(-2).replace(/^0*/g, "") || "0";
      return `${year}/${month}/${day}`;
    },
  },
  Zone3: {
    Zone5: (value) =>
      fromCode(
        Math.min(Number(value.replace(/\//g, "")), Number.MAX_VALUE)
          .toString(16)
          .toUpperCase(),
      ),
    Zone6: (value) => toDigits(value.replace(/\//g, ""), 26),
    Zone4: (value) => (isValidDate(value) ? dateName(value) : [null, value]),
    Zone2: (value) => toDigits(value.replace(/\//g, ""), 16),
    Zone1: (value) => calcDate(value.split("/").map((part) => Number(part))),
  },
  Zone4: {
    Zone5: (value) =>
      findClosestKey(TERMINUS_EMOJI_TABLE, value, "name") ?? [null, value],
    Zone6: (value) => value.replace(/ /g, ""),
    Zone2: (value) =>
      findClosestKey(TERMINUS_COLOR_TABLE, value, "name") ?? [null, value],
    Zone1: (value) => parseNumber(value),
    Zone3: (value) => parseDate(value),
  },
  Zone5: {
    Zone6: (value) => {
      const code = TERMINUS_EMOJI_TABLE[value].code;
      let out = "";
      for (const digit of code) {
        out += HEX_TO_LETTER[digit];
      }
      return out;
    },
    Zone4: (value) => TERMINUS_EMOJI_TABLE[value].name,
    Zone2: (value) => colorify(TERMINUS_EMOJI_TABLE[value].code),
    Zone1: (value) => parseInt(TERMINUS_EMOJI_TABLE[value].code, 16),
    Zone3: (value) => `${parseInt(TERMINUS_EMOJI_TABLE[value].code, 16)}/1/1`,
  },
  Zone6: {
    Zone5: (value) => {
      let hex = "";
      for (const character of value) {
        hex += LETTER_TO_HEX[character];
      }
      return fromCode(hex);
    },
    Zone4: (value) => {
      if (value.length === 0) return "";
      let result = value[0];
      for (let i = 1; i < value.length; i += 1) {
        result += " " + value[i];
      }
      return result;
    },
    Zone2: (value) => {
      let hex = "";
      for (const character of value) {
        hex += LETTER_TO_HEX[character];
      }
      return hex;
    },
    Zone1: parseBase26,
    Zone3: (value) => `${parseBase26(value)}/1/1`,
  },
};

export const overallConversions = <T extends TerminusType>(
  type: T,
  value: TypeValueMap[T],
): Record<TerminusType, ConversionResult<TypeValueMap[TerminusType]>> => {
  const results: Record<
    TerminusType,
    ConversionResult<TypeValueMap[TerminusType]>
  > = {} as Record<TerminusType, ConversionResult<TypeValueMap[TerminusType]>>;

  for (const targetType of TERMINUS_TYPES) {
    if (targetType === type) {
      results[targetType] = value as TypeValueMap[TerminusType];
      continue;
    }
    const converter = convertFunctions[type]?.[targetType];
    if (!converter) {
      throw new Error(`Missing converter from ${type} to ${targetType}`);
    }
    results[targetType] = converter(value);
  }

  return results;
};
