const DEFAULT_TERMINUS_RATE_LIMIT_SECONDS = 1;
const terminusRateLimitEnv = Number.parseInt(
  typeof process !== "undefined"
    ? (process.env.TERMINUS_RATE_LIMIT_SECONDS ?? "")
    : "",
  10,
);

export const TERMINUS_RATE_LIMIT_SECONDS =
  !Number.isNaN(terminusRateLimitEnv) &&
  Number.isFinite(terminusRateLimitEnv) &&
  terminusRateLimitEnv > 0
    ? terminusRateLimitEnv
    : DEFAULT_TERMINUS_RATE_LIMIT_SECONDS;

export const TERMINUS_INPUT_MAX_CHARACTERS = 2000;

// Replace trailing \ufe0f (emoji modifier) when it follows a single character
// (e.g. the heart emoji). This is due to the structure of our emoji table.
export const normalizeTerminusValue = (value: string): string =>
  value
    .trim()
    .replace(/\s+/g, " ")
    .replace(/^(.)\ufe0f$/g, "$1")
    .toUpperCase();

export const TERMINUS_INPUT_LENGTH_ERROR = `Destinations are limited to ${TERMINUS_INPUT_MAX_CHARACTERS} characters.`;

export const getTerminusInputLengthError = (
  normalizedValue: string,
): string | null => {
  return normalizedValue.length > TERMINUS_INPUT_MAX_CHARACTERS
    ? TERMINUS_INPUT_LENGTH_ERROR
    : null;
};
