export const HEX_TO_LETTER: Record<string, string> = Object.fromEntries(
  Array.from({ length: 16 }, (_, index) => [
    index.toString(16).toUpperCase(),
    String.fromCharCode(65 + index),
  ]),
);

export const LETTER_TO_HEX: Record<string, string> = Object.fromEntries(
  Array.from({ length: 26 }, (_, index) => [
    String.fromCharCode(65 + index),
    (index % 16).toString(16).toUpperCase(),
  ]),
);

export const CODE_TABLE: Record<string, string> = Object.fromEntries(
  Object.entries(TERMINUS_EMOJI_TABLE).map(([emoji, details]) => [
    details.code,
    emoji,
  ]),
);

export const DICTIONARY = new Set(WORD_LIST.map((word) => word.toUpperCase()));

export const parseBase26 = (value: string): number => {
  let accumulator = 0;
  for (let index = 0; index < value.length; index += 1) {
    const character = value[index];
    if (character.charCodeAt(0) === 65) {
      continue;
    }
    accumulator +=
      (character.charCodeAt(0) - 65) * Math.pow(26, value.length - index - 1);
  }
  return Math.min(accumulator, Number.MAX_VALUE);
};

export const toBase26 = (value: number): string => {
  if (value === 0) {
    return "A";
  }
  let result = "";
  let current = value;
  while (current > 0) {
    result = String.fromCharCode((current % 26) + 65) + result;
    current = Math.floor(current / 26);
  }
  return result;
};

export const toDigits = (value: string, base: 16 | 26): string => {
  let remainder = value;
  let result = "";
  while (remainder) {
    const length =
      remainder.length >= 2 && Number(remainder.slice(0, 2)) < base ? 2 : 1;
    const segment = remainder.slice(0, length);
    result +=
      base === 16
        ? Number(segment).toString(16).toUpperCase()
        : String.fromCharCode(65 + Number(segment));
    remainder = remainder.slice(length);
  }
  return result;
};

export const fromCode = (code: string): ConversionResult<string, string> => {
  const lookup = CODE_TABLE[code.replace(/^0+/g, "")];
  return lookup ?? [null, code];
};

export const colorify = (value: string): string =>
  value.length <= 6 ? value.padStart(6, "0") : value.slice(0, 6);

export const findClosestKey = (
  table: Record<string, Record<string, unknown>>,
  target: string,
  key: string,
): string | undefined => {
  let bestKey: string | undefined;
  let bestDistance = Number.POSITIVE_INFINITY;
  const normalizedTarget = normalizeTerminusValue(target);

  for (const candidate of Object.keys(table).sort()) {
    const entry = table[candidate][key];
    const normalizedEntry = normalizeTerminusValue(String(entry));
    const distance = levenshtein(normalizedTarget, normalizedEntry);
    if (distance < bestDistance) {
      bestDistance = distance;
      bestKey = candidate;
    }
  }

  return bestKey;
};

export const levenshtein = (a: string, b: string): number => {
  if (a === b) {
    return 0;
  }

  let source = a;
  let target = b;
  if (source.length > target.length) {
    [source, target] = [target, source];
  }

  const previous = Array.from(
    { length: source.length + 1 },
    (_, index) => index,
  );

  for (let j = 1; j <= target.length; j += 1) {
    let upperLeft = previous[0];
    previous[0] = j;
    for (let i = 1; i <= source.length; i += 1) {
      const temp = previous[i];
      const cost = source[i - 1] === target[j - 1] ? 0 : 1;
      previous[i] = Math.min(
        previous[i] + 1,
        previous[i - 1] + 1,
        upperLeft + cost,
      );
      upperLeft = temp;
    }
  }

  return previous[source.length];
};

export const calcDate = (parts: number[]): ConversionResult<number, string> => {
  const [rawNumerator, divisorOne, divisorTwo] = parts;
  const numerator = Math.min(rawNumerator, Number.MAX_VALUE);
  const denominator = Math.min(divisorOne * divisorTwo, Number.MAX_VALUE);
  if (denominator === 0 || numerator % denominator !== 0) {
    return [null, `${numerator}/${denominator}`];
  }
  return numerator / denominator;
};

export const gcd = (a: number, b: number): number => {
  if (a > b) {
    return gcd(b, a);
  }
  if (a === 0) {
    return Math.max(b, 1);
  }
  return gcd(b % a, a);
};

export const simplify = (a: number, b: number): string => {
  const divisor = gcd(a, b);
  return `${a / divisor}/${b / divisor}`;
};

export const colorDistance = (a: string, b: string): number =>
  [0, 2, 4]
    .map((index) =>
      Math.abs(
        parseInt(a.slice(index, index + 2), 16) -
          parseInt(b.slice(index, index + 2), 16),
      ),
    )
    .reduce((accumulator, value) => accumulator + value, 0);

export const closestColor = (value: string, colors: string[]): string[] => {
  let bestDistance = Number.POSITIVE_INFINITY;
  const results: string[] = [];

  for (const candidate of colors) {
    const distance = colorDistance(value, candidate);
    if (distance < bestDistance) {
      bestDistance = distance;
      results.length = 0;
      results.push(candidate);
    } else if (distance === bestDistance) {
      results.push(candidate);
    }
  }

  return results;
};

export const getWordData = (value: string): number[] => {
  const results: number[] = [];
  if (value.length === 5) {
    results.push(0);
  }
  const target = "CROWS";
  for (let index = 0; index < target.length; index += 1) {
    if (value.includes(target[index])) {
      results.push(index + 1);
    }
  }
  return results;
};

export const FACTORS: number[] = [2, 3, 7, 17, 61];

export const dateProps = (value: string): number[] => {
  const [year, month, day] = value.split("/").map((part) => Number(part));
  const facts = [
    Math.floor(year / 1000) % 10 === 2,
    Math.floor(year / 100) % 10 === 0,
    Math.floor(year / 10) % 10 === 6,
    year % 10 === 9,
    month === 3,
    day === 3,
    dayOfWeek([year, month, day]) === 0,
  ];
  return facts
    .map((flag, index) => [flag, index] as const)
    .filter(([flag]) => flag)
    .map(([, index]) => index);
};

export const handleColorPuzzles = (value: string): number[] => {
  const differences = [0, 2, 4].map(
    (index, component) =>
      parseInt(value.slice(index, index + 2), 16) -
      [0xad, 0xa5, 0x48][component],
  );
  const scores = [
    differences[0] + differences[1] + differences[2],
    differences[0] - differences[1] - differences[2],
    -differences[0] + differences[1] - differences[2],
    -differences[0] - differences[1] + differences[2],
  ];
  const maxScore = Math.max(...scores);
  return [0, 1, 2, 3].filter((index) => scores[index] === maxScore);
};

export const conversionFailureDisplay = (
  targetType: TerminusType,
  value: unknown,
  solved: boolean,
): string => {
  const detail = solved ? ` (${String(value)})` : "";
  return `Type conversion failed${detail}`;
};

export const formatValidationFailure = (
  solved: boolean,
  originValue: TypeValueMap[TerminusType],
  convertedValue: TypeValueMap[TerminusType],
  reason: string,
  targetType: TerminusType,
  obfuscate: ObfuscateFn,
): string => {
  const message =
    "Getting puzzle failed (" +
    (solved
      ? `${obfuscate(
          originValue as TypeValueMap[TerminusType],
          convertedValue,
          targetType,
        )} is `
      : "") +
    reason +
    ")";
  return message.replace(/is ~/g, "has ").replace(/\(~/g, "(");
};

export const isFailure = <T, F = unknown>(
  value: ConversionResult<T, F>,
): value is ConversionFailure<F> => Array.isArray(value) && value[0] === null;

export const isValidPermutedDate = (value: string): boolean => {
  const parts = value.split("/");
  if (parts.length !== 3) {
    return false;
  }
  const [year, month, day] = parts;
  return (
    isValidDate(`${day}/${year}/${month}`) ||
    isValidDate(`${day}/${month}/${year}`)
  );
};

export const isDayOfMonthStringValid = (value: string): boolean => {
  if (!inYMDFormat(value)) {
    return false;
  }
  const [year, month, day] = value.split("/").map((part) => Number(part));
  return isValidDayOfMonthNumeric(month, day, isLeapYear(year));
};

export const validMonth = (value: string): boolean => {
  const parts = value.split("/");
  if (parts.length !== 3) {
    return false;
  }
  const month = Number(parts[1]);
  return month >= 1 && month <= 12;
};

