import { type TerminusType } from "@hunt/hunt-data";
import { TERMINUS_EMOJI_TABLE, TERMINUS_TEXTS } from "./data";
import {
  dateProps,
  DICTIONARY,
  FACTORS,
  getWordData,
  handleColorPuzzles,
  isDayOfMonthStringValid,
  isValidDate,
  isValidPermutedDate,
  validMonth,
} from "./helpers";
import type { TypeValueMap, ValidationResult } from "./types";
import { inYMDFormat } from "./utility";

export const TARGETS: Record<TerminusType, TypeValueMap[TerminusType][]> = {
  Zone1: [43554],
  Zone2: ["ADA548"],
  Zone3: ["2069/3/3"],
  Zone4: TERMINUS_TEXTS,
  Zone5: ["🦧"],
  Zone6: ["CROWS"],
};

export const SPECIAL_META: Record<TerminusType, TypeValueMap[TerminusType]> = {
  Zone1: 666,
  Zone2: "1560BD",
  Zone3: "1944/6/6",
  Zone4: "BUBBLE TEA",
  Zone5: "📎",
  Zone6: "EVENTS",
};

export const TYPE_NAME_TABLE: Record<TerminusType, string> = {
  Zone1: "Number",
  Zone2: "Color",
  Zone3: "Date",
  Zone4: "Sentence",
  Zone5: "Emoji",
  Zone6: "Word",
};

export const validateResult: {
  [K in TerminusType]: (value: TypeValueMap[K]) => ValidationResult[];
} = {
  Zone1: (value) => [
    [value !== 0, "is zero"],
    [value < Math.pow(10, 15), "is too big"],
  ],
  Zone2: (value) => [[value.length === 6, "is not length 6"]],
  Zone3: (value) => [
    [inYMDFormat(value), "is not in proper format"],
    [
      !isValidPermutedDate(value) || isValidDate(value),
      "is not in YYYY/MM/DD format",
    ],
    [validMonth(value), "has invalid M"],
    [isDayOfMonthStringValid(value), "has invalid D"],
    [Number(value.split("/")[0]) > 0, "is in Y zero"],
    [Number(value.split("/")[0]) < 10000, "is too far in the future"],
  ],
  Zone4: (value) => [
    [value.trim().split(/\s+/).length > 1, "is only one word"],
    [TERMINUS_TEXTS.some((entry) => entry.includes(value)), "is not in poem"],
  ],
  Zone5: (value) => [
    [value in TERMINUS_EMOJI_TABLE, "is not the right type of character"],
  ],
  Zone6: (value) => [[DICTIONARY.has(value), "is not in dictionary"]],
};

export const resultFunctions: {
  [K in TerminusType]: (value: TypeValueMap[K]) => number[];
} = {
  Zone1: (value) => [0, 1, 2, 3, 4].filter((i) => value % FACTORS[i] === 0),
  Zone2: (value) => handleColorPuzzles(value),
  Zone3: (value) => dateProps(value),
  Zone4: (value) => [Math.min(6, value.trim().split(/\s+/).length) - 2],
  Zone5: (value) => TERMINUS_EMOJI_TABLE[value].criteria,
  Zone6: (value) => getWordData(value),
};
