import type { ConversionResult } from "./types";

export type ParseFailure<T = string> = [null, T];
export type ParseResult<T, E = string> = T | ParseFailure<E>;

const SMALL_NUMBER_WORDS: string[] = [
  "ZERO",
  "ONE",
  "TWO",
  "THREE",
  "FOUR",
  "FIVE",
  "SIX",
  "SEVEN",
  "EIGHT",
  "NINE",
  "TEN",
  "ELEVEN",
  "TWELVE",
  "THIRTEEN",
  "FOURTEEN",
  "FIFTEEN",
  "SIXTEEN",
  "SEVENTEEN",
  "EIGHTEEN",
  "NINETEEN",
];

const TENS_WORDS: string[] = [
  "X",
  "X",
  "TWENTY",
  "THIRTY",
  "FORTY",
  "FIFTY",
  "SIXTY",
  "SEVENTY",
  "EIGHTY",
  "NINETY",
];

const SCALE_WORDS = new Map<string, number>([
  ["THOUSAND", 1_000],
  ["MILLION", 1_000_000],
  ["BILLION", 1_000_000_000],
  ["TRILLION", 1_000_000_000_000],
]);

const MONTH_WORDS: string[] = [
  "X",
  "JANUARY",
  "FEBRUARY",
  "MARCH",
  "APRIL",
  "MAY",
  "JUNE",
  "JULY",
  "AUGUST",
  "SEPTEMBER",
  "OCTOBER",
  "NOVEMBER",
  "DECEMBER",
];

const ORDINAL_WORDS: string[] = [
  "X",
  "FIRST",
  "SECOND",
  "THIRD",
  "FOURTH",
  "FIFTH",
  "SIXTH",
  "SEVENTH",
  "EIGHTH",
  "NINTH",
  "TENTH",
  "ELEVENTH",
  "TWELFTH",
  "THIRTEENTH",
  "FOURTEENTH",
  "FIFTEENTH",
  "SIXTEENTH",
  "SEVENTEENTH",
  "EIGHTEENTH",
  "NINETEENTH",
];

const TENS_ORDINAL_WORDS = {
  TWENTIETH: 20,
  THIRTIETH: 30,
} as const;

export function numberName(value: number): string {
  if (value < 20) {
    return SMALL_NUMBER_WORDS[value];
  }
  if (value < 100) {
    const tens = Math.floor(value / 10);
    const remainder = value % 10;
    return (
      TENS_WORDS[tens] + (remainder ? " " + SMALL_NUMBER_WORDS[remainder] : "")
    );
  }
  if (value < 1000) {
    const hundreds = Math.floor(value / 100);
    const remainder = value % 100;
    return (
      SMALL_NUMBER_WORDS[hundreds] +
      " HUNDRED" +
      (remainder ? " AND " + numberName(remainder) : "")
    );
  }
  // Need to start with the biggest units to avoid things like THOUSAND THOUSAND.
  for (const [word, scale] of [...SCALE_WORDS].reverse()) {
    if (value >= scale) {
      const head = Math.floor(value / scale);
      const tail = value % scale;
      return (
        numberName(head) +
        " " +
        word +
        (tail ? (tail < 100 ? " AND " : " ") + numberName(tail) : "")
      );
    }
  }

  return value.toString();
}

export function ordinal(value: number): string {
  if (value < ORDINAL_WORDS.length) {
    return ORDINAL_WORDS[value];
  }
  if (value % 10 === 0) {
    return (
      Object.keys(TENS_ORDINAL_WORDS).find(
        (key) =>
          TENS_ORDINAL_WORDS[key as keyof typeof TENS_ORDINAL_WORDS] === value,
      ) ?? ""
    );
  }
  return `${TENS_WORDS[Math.floor(value / 10)]} ${ORDINAL_WORDS[value % 10]}`;
}

export function dateName(date: string): ConversionResult<string> {
  const [yearStr, monthStr, dayStr] = date.split("/");
  const year = Number(yearStr);
  const month = Number(monthStr);
  const day = Number(dayStr);
  // Handle the case of an extremely large year
  if (year >= 1e15) {
    return [null, Math.min(year, Number.MAX_VALUE).toString()];
  }
  return `${MONTH_WORDS[month]} ${ordinal(day)} ${numberName(year)}`;
}

export function parseNumber(input: string): ParseResult<number> {
  const tokens = input.split(" ");
  if (tokens.length === 0) {
    return [null, input];
  }
  const parsed = parseNumberWords(tokens);
  if (parsed === null || numberName(parsed) !== input) {
    return [null, input];
  }
  return parsed;
}

export function parseDate(input: string): ParseResult<string> {
  const tokens = input.split(" ");
  if (tokens.length === 0) {
    return [null, input];
  }
  const parsed = parseDateWords(tokens);
  if (parsed === null || dateName(parsed) !== input) {
    return [null, input];
  }
  return parsed;
}

export function dayOfWeek([year, month, day]: [
  number,
  number,
  number,
]): number {
  const previousYear = year - 1;
  const baseDays =
    previousYear * 365 +
    Math.floor(previousYear / 4) -
    Math.floor(previousYear / 100) +
    Math.floor(previousYear / 400);
  const monthDays = DAYS_BY_MONTH.slice(0, month - 1).reduce(
    (acc, value) => acc + value,
    0,
  );
  const leapAdjustment = isLeapYear(year) && month > 2 ? 1 : 0;
  return (baseDays + monthDays + day + leapAdjustment) % 7;
}

export function isLeapYear(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

export function isValidDayOfMonth(
  month: number,
  day: number,
  leapYear: boolean,
): boolean {
  return (
    (day >= 1 && day <= DAYS_BY_MONTH[month - 1]) ||
    (month === 2 && day === 29 && leapYear)
  );
}

export function isValidDayOfYear(
  month: number,
  day: number,
  leapYear: boolean,
): boolean {
  return month >= 1 && month <= 12 && isValidDayOfMonth(month, day, leapYear);
}

export function inYMDFormat(value: string): boolean {
  const parts = value.split("/");
  return parts.length === 3 && parts.every((part) => /^[0-9]+$/.test(part));
}

export function isValidDate(value: string): boolean {
  if (!inYMDFormat(value)) {
    return false;
  }
  const [yearStr, monthStr, dayStr] = value.split("/");
  const year = Number(yearStr);
  const month = Number(monthStr);
  const day = Number(dayStr);
  return (
    year > 0 &&
    month < 100 &&
    day < 100 &&
    isValidDayOfYear(month, day, isLeapYear(year))
  );
}

const DAYS_BY_MONTH = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31] as const;

function parseNumberWords(words: string[]): number | null {
  if (words.length === 0) {
    return 0;
  }

  let total = 0;
  let current = 0;

  for (const word of words) {
    if (word === "AND") {
      continue;
    }
    if (word === "HUNDRED") {
      if (current === 0) {
        return null;
      }
      current *= 100;
      continue;
    }
    const scale = SCALE_WORDS.get(word);
    if (scale) {
      if (current === 0) {
        return null;
      }
      total += current * scale;
      current = 0;
      continue;
    }
    const value =
      PARSE_NUMBER_LOOKUP.get(word) ??
      (word in TENS_ORDINAL_WORDS
        ? TENS_ORDINAL_WORDS[word as keyof typeof TENS_ORDINAL_WORDS]
        : undefined);
    if (value === undefined) {
      return null;
    }
    current += value;
  }

  return total + current;
}

function parseDateWords(words: string[]): string | null {
  if (words.length < 2) {
    return null;
  }

  const monthIndex = MONTH_WORDS.indexOf(words[0]);
  if (monthIndex === -1) {
    return null;
  }

  const [day, consumed] = parseDayWords(words.slice(1));
  if (day === null) {
    return null;
  }

  const yearWords = words.slice(1 + consumed);
  const year = parseNumberWords(yearWords);
  if (year === null) {
    return null;
  }

  return `${year}/${monthIndex}/${day}`;
}

function parseDayWords(words: string[]): [number | null, number] {
  if (words.length === 0) {
    return [null, 0];
  }

  const [first, second] = words;
  if (first === "TWENTY" || first === "THIRTY") {
    if (!second) {
      return [null, 0];
    }
    const suffix = ORDINAL_WORDS.indexOf(second);
    if (suffix === -1) {
      return [null, 0];
    }
    const base = first === "TWENTY" ? 20 : 30;
    return [base + suffix, 2];
  }

  if (first in TENS_ORDINAL_WORDS) {
    return [TENS_ORDINAL_WORDS[first as keyof typeof TENS_ORDINAL_WORDS], 1];
  }

  const ordinalIndex = ORDINAL_WORDS.indexOf(first);
  if (ordinalIndex !== -1) {
    return [ordinalIndex, 1];
  }

  return [null, 0];
}

const PARSE_NUMBER_LOOKUP = new Map<string, number>(
  [
    ...SMALL_NUMBER_WORDS.map<[string, number]>((word, index) => [word, index]),
    ...TENS_WORDS.map<[string, number]>((word, index) => [word, 10 * index]),
  ].filter(([word]) => word !== "X"),
);
