import { type TerminusType } from "@hunt/hunt-data";
import { TERMINUS_EMOJI_TABLE } from "./data";
import type { ParsedEntry, TypeValueMap } from "./types";

type ParseFunctionMap = {
  [K in TerminusType]: (input: string) => TypeValueMap[K] | null;
};

// Parse order for Terminus types. This mostly doesn't matter,
// but it is important that Color (Zone2) is parsed after Number and Word,
// so that ambiguous inputs will be parsed as Number/Word rather than Color.
const TERMINUS_TYPES_IN_PARSE_ORDER = [
  "Zone1",
  "Zone3",
  "Zone4",
  "Zone5",
  "Zone6",
  "Zone2",
] as const;

// Note: The input is already normalized at this point.
export const parseFunctions: ParseFunctionMap = {
  Zone1: (input) =>
    /^[0-9]+$/.test(input) ? Math.min(Number(input), Number.MAX_VALUE) : null,
  Zone2: (input) => (/^[0-9A-F]{6}$/.test(input) ? input : null),
  Zone3: (input) =>
    /^[0-9]+\/[0-9]+\/[0-9]+$/.test(input)
      ? input
          .replace(/^0+/g, "")
          .replace(/\/0+/g, "/")
          .replace(/^\//g, "0/")
          .replace(/\/\//g, "/0/")
          .replace(/\/$/g, "/0")
      : null,
  Zone4: (input) =>
    /^[A-Z ]+$/.test(input) && input.includes(" ") ? input : null,
  Zone5: (input) =>
    Object.prototype.hasOwnProperty.call(TERMINUS_EMOJI_TABLE, input)
      ? input
      : null,
  Zone6: (input) => (/^[A-Z]+$/.test(input) ? input : null),
};

export const overallParse = (input: string): ParsedEntry | null => {
  for (const type of TERMINUS_TYPES_IN_PARSE_ORDER) {
    const parsed = parseFunctions[type](input);
    if (parsed !== null) {
      return { type, value: parsed } as ParsedEntry;
    }
  }
  return null;
};
